package com.bank.aml.service;

import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.logging.Logger;

// Finds the start index of every consecutive block that is an anagram of the combo.
public class AmlPatternScanner {
    private static final Logger log = Logger.getLogger(AmlPatternScanner.class.getName());

    public List<Integer> findSuspiciousBlockStarts(String flags, String combo) {
        List<Integer> starts = new ArrayList<>();
        if (flags == null || combo == null || flags.length() < combo.length()
                || combo.isEmpty()) {
            return starts;
        }
        Map<Character, Integer> need = new HashMap<>();
        for (char c : combo.toCharArray()) {
            need.merge(c, 1, Integer::sum);
        }
        int requiredDistinct = need.size();
        Map<Character, Integer> window = new HashMap<>();
        int matches = 0;
        int w = combo.length();

        for (int right = 0; right < flags.length(); right++) {
            char in = flags.charAt(right);
            if (need.containsKey(in)) {
                int cnt = window.merge(in, 1, Integer::sum);
                if (cnt == need.get(in)) matches++;
                else if (cnt == need.get(in) + 1) matches--;
            }
            if (right >= w) {
                char out = flags.charAt(right - w);
                if (need.containsKey(out)) {
                    int cnt = window.merge(out, -1, Integer::sum);
                    if (cnt == need.get(out)) matches++;
                    else if (cnt == need.get(out) - 1) matches--;
                }
            }
            if (matches == requiredDistinct) {
                int start = right - w + 1;
                starts.add(start);
                final int s = start;
                log.fine(() -> "Suspicious block starts at index " + s);
            }
        }
        log.info(() -> "Suspicious block starts in '" + flags + "' for combo '"
                + combo + "' = " + starts);
        return starts;
    }
}
